  if("N06".equals(step.nodeKind())){var declared=original.document().required("node_business_original").required("applicability");var template=declared.required("template");var current=applicability.requireTarget(a,j.projectId(),text(admission.required("profile_revision"),"version_id"),text(template.required("content"),"document_type"),text(template,"template_version"),"EVALUATION_RESULTS");same(json.tree(current.view()),declared);applicability.requireUnchanged(a,current);}
  if("N03".equals(step.nodeKind())){var business=original.document().required("node_business_original");same(json.tree(StrictComparisonPolicyService.implementation()),business.required("implementation"));for(var declared:business.required("policies")){var policy=comparisonPolicies.requireApproved(a,j.projectId(),text(declared,"revision"),text(declared,"sha256"));same(json.tree(policy.definition()),declared.required("definition"));policy.requireUnchanged();}}
