  var predecessors=new ArrayList<Predecessor>();for(String kind:requiredPredecessors(step.nodeKind())){var applicable=j.nodes().stream().filter(x->kind.equals(x.node().nodeKind())).toList();if(applicable.isEmpty())continue;var prior=one(applicable);var completed=runtime.getObject().requireOriginalCompleted(a,run,prior.stepId());var output=objects.readOriginal(a,run,prior.stepId(),"BUSINESS_OUTPUT");same(completed.sessionId(),output.sessionId());same(completed.output(),new PermissionProtocol.Basis(output.artifact().artifactId(),output.artifact().sha256()));var envelope=objects.readOriginal(a,run,prior.stepId(),"STEP_ENVELOPE");var priorCompiler=schema.read(envelope.payload().getBytes(StandardCharsets.UTF_8)).required("compiler");predecessors.add(new Predecessor(prior,output,completed.sessionId(),priorCompiler.path("node_business_original").isMissingNode()?json.tree(null):priorCompiler.required("node_business_original")));}
